// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — Bluetooth Handler (Module 10 v2 — Step 10.5). * * Toggles Bluetooth on/off. Mirrors [WifiHandler]'s design with API-level * graceful degradation. * * ## API level behavior (per strategy §"Privacy & Security") * *  - **API 30 and below**: `BluetoothAdapter.enable` / `disable` works *    directly. Requires `BLUETOOTH_ADMIN` permission (deprecated on 31+). *    Async toggle — `enable()` returns true if the request was accepted, *    actual state changes via `BluetoothAdapter.ACTION_STATE_CHANGED` *    broadcast. * *  - **API 31+ (Android 12+)**: Google blocked programmatic Bluetooth *    toggle. The handler **opens `Settings.Panel.ACTION_BT`** for the *    user to toggle manually. Also requires `BLUETOOTH_CONNECT` permission *    to even query the adapter state. * * ## Idempotent execution (Review 2 Elite 1) * * If Bluetooth is already in the target state, skip the hardware call. * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous on/off state. Undo restores the actual previous * state. * * ## Resource category * * Bluetooth uses [ResourceCategory.CONNECTIVITY]. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Connectivity</a> */class BluetoothHandler(    private val bluetoothService: BluetoothService,) : ReversibleHandler<SystemOperation.SetBluetooth> {    override val id: String = "bluetooth"    override val displayName: String = "Bluetooth Control"    override val requiredPermissions: Set<String> = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S) {        setOf(android.Manifest.permission.BLUETOOTH_CONNECT)    } else {        emptySet()  // pre-31 doesn't need runtime perms for enable/disable    }    override val resourceCategory: ResourceCategory = ResourceCategory.CONNECTIVITY    override fun isAvailable(): Boolean = bluetoothService.isAvailable()    override suspend fun execute(operation: SystemOperation.SetBluetooth): Result<Unit> {        if (!isAvailable()) {            return Result.Failure(                error = AppError.Hardware.Unavailable("bluetooth"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        return try {            if (bluetoothService.canToggleDirectly()) {                // API 30- — direct toggle.                val success = bluetoothService.setEnabled(operation.on)                if (success) {                    Result.Success(Unit, CorrelationId.generate(), 0)                } else {                    Result.Failure(                        error = AppError.Hardware.Unknown("bluetooth"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            } else {                // API 31+ — open Settings.Panel.                val launched = bluetoothService.openSettingsPanel()                if (launched) {                    Result.Success(                        data = Unit,                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                        warnings = listOf("opened_settings_panel"),                    )                } else {                    Result.Failure(                        error = AppError.Hardware.Unsupported("bluetooth_panel"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            }        } catch (t: Throwable) {            Timber.tag("BluetoothHandler").w("execute failed", t)            Result.Failure(                error = AppError.Hardware.Unknown("bluetooth", t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    override suspend fun capturePreState(operation: SystemOperation.SetBluetooth): Any? {        return try {            BluetoothPreState(wasEnabled = bluetoothService.isEnabled())        } catch (t: Throwable) {            Timber.tag("BluetoothHandler").w("capturePreState failed", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetBluetooth, preState: Any?) {        if (preState !is BluetoothPreState) return        try {            if (bluetoothService.canToggleDirectly()) {                bluetoothService.setEnabled(preState.wasEnabled)            } else {                Timber.tag("BluetoothHandler").i("Undo: Bluetooth was ${if (preState.wasEnabled) "on" else "off"} — opening panel for manual restore.")                bluetoothService.openSettingsPanel()            }        } catch (t: Throwable) {            Timber.tag("BluetoothHandler").w("restorePreState failed", t)        }    }    override suspend fun getCurrentState(): Any? = try {        BluetoothPreState(wasEnabled = bluetoothService.isEnabled())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetBluetooth): Boolean {        return try {            bluetoothService.isEnabled() == operation.on        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetBluetooth): String =        if (operation.on) "Bluetooth turned on" else "Bluetooth turned off"    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is BluetoothPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"BluetoothPreState\",\"wasEnabled\":${preState.wasEnabled}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "BluetoothPreState" -> BluetoothPreState(wasEnabled = (map["wasEnabled"] as? Boolean) ?: false)            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for Bluetooth (previous on/off). */    data class BluetoothPreState(val wasEnabled: Boolean)}
